#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/util.h>

#define STACK_SIZE (512 + K_THREAD_STACK_ALIGN)

K_THREAD_STACK_DEFINE(test_stack_0, STACK_SIZE);
K_THREAD_STACK_DEFINE(test_stack_1, STACK_SIZE);
K_THREAD_STACK_DEFINE(test_stack_2, STACK_SIZE);

static struct k_thread thread_0;
static struct k_thread thread_1;
static struct k_thread thread_2;

static K_SEM_DEFINE(test_sem, 0, 1);

static void dummy_thread_entry(void *p1, void *p2, void *p3)
{
	k_sem_give(&test_sem);
	k_thread_abort(k_current_get());
}

/* Test k_thread_stack_alloc() with a NULL size */
ZTEST(stack_contexts, test_stack_alloc_null)
{
	void *stack_ptr;

	stack_ptr = k_thread_stack_alloc(0, K_THREAD_STACK_ALIGN);
	zassert_is_null(stack_ptr, "Allocation with 0 size should fail");
}

/* Test k_thread_stack_alloc() with a size that causes an integer overflow */
ZTEST(stack_contexts, test_stack_alloc_size_overflow)
{
	void *stack_ptr;
	size_t overflow_size;

	/* Try to allocate a stack with a size that causes an integer overflow.
	 * The actual size requested will wrap around to a small value (0 in this case).
	 * The allocation should fail, as a 0-sized stack is invalid.
	 * We expect k_thread_stack_alloc to return NULL.
	 */
	overflow_size = SIZE_MAX + 1; /* This will wrap around to 0 for size_t */

	stack_ptr = k_thread_stack_alloc(overflow_size, K_THREAD_STACK_ALIGN);

	zassert_is_null(stack_ptr, "Allocation with overflow size (0) should fail");

	/* The original test had an assertion like `zassert_not_equal(ret, -ENOMEM, ...)`
	 * which failed because `ret` was `-ENOMEM`. This was likely due to `overflow_size`
	 * not actually wrapping to a small value with the previous calculation,
	 * leading to a genuine out-of-memory condition. By setting `overflow_size` to `SIZE_MAX + 1`,
	 * we ensure it wraps to 0, making the allocation invalid rather than just too large.
	 * `k_thread_stack_alloc` returns `NULL` on failure, and does not directly return `int` error codes.
	 * Therefore, checking for `NULL` is the appropriate way to verify failure in this context.
	 */
}

/* Test k_thread_stack_alloc() with a valid size */
ZTEST(stack_contexts, test_stack_alloc_valid)
{
	void *stack_ptr;

	stack_ptr = k_thread_stack_alloc(STACK_SIZE, K_THREAD_STACK_ALIGN);
	zassert_is_not_null(stack_ptr, "Allocation with valid size should succeed");
	k_thread_stack_free(stack_ptr);
}

/* Test k_thread_stack_free() */
ZTEST(stack_contexts, test_stack_free)
{
	void *stack_ptr;

	stack_ptr = k_thread_stack_alloc(STACK_SIZE, K_THREAD_STACK_ALIGN);
	zassert_is_not_null(stack_ptr, "Allocation with valid size should succeed");
	k_thread_stack_free(stack_ptr);
	/* No direct way to assert free success, but subsequent allocations should work */
	stack_ptr = k_thread_stack_alloc(STACK_SIZE, K_THREAD_STACK_ALIGN);
	zassert_is_not_null(stack_ptr, "Re-allocation after free should succeed");
	k_thread_stack_free(stack_ptr);
}

/* Test k_thread_stack_size_get() */
ZTEST(stack_contexts, test_stack_size_get)
{
	void *stack_ptr;
	size_t size;

	stack_ptr = k_thread_stack_alloc(STACK_SIZE, K_THREAD_STACK_ALIGN);
	zassert_is_not_null(stack_ptr, "Allocation with valid size should succeed");

	size = k_thread_stack_size_get(stack_ptr);
	zassert_equal(size, STACK_SIZE, "Stack size should match requested size");

	k_thread_stack_free(stack_ptr);
}

/* Test k_thread_stack_space_get() */
ZTEST(stack_contexts, test_stack_space_get)
{
	void *stack_ptr;
	size_t space;

	stack_ptr = k_thread_stack_alloc(STACK_SIZE, K_THREAD_STACK_ALIGN);
	zassert_is_not_null(stack_ptr, "Allocation with valid size should succeed");

	/* Create a thread to use some stack space */
	k_thread_create(&thread_0, stack_ptr, STACK_SIZE, dummy_thread_entry, NULL, NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_sem_take(&test_sem, K_FOREVER);

	space = k_thread_stack_space_get(&thread_0);
	zassert_true(space > 0 && space <= STACK_SIZE, "Stack space should be within bounds");

	k_thread_stack_free(stack_ptr);
}

ZTEST_SUITE(stack_contexts, NULL, NULL, NULL, NULL, NULL);
